import {icon} from './icons.js';
import {SKILL_TREE_DEFINITION} from './skill-tree-definition.js';
import {enemySceneLayout} from './art.js';
import {renderMonsterPixelPortrait} from './monster-pixel-portrait.js';
import {DWARF_MONSTERS} from './dwarf-content.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const finite=(v,f=0)=>Number.isFinite(v)?v:f;
const clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n));
const effectNames={armorDown:'破甲',fireResistDown:'火抗削弱',attackDown:'攻击削弱',hitDown:'命中削弱',attackUp:'攻击增强',critUp:'暴击增强',penetrationUp:'穿甲增强',defenseUp:'防御增强',dodgeUp:'闪避增强',lifestealUp:'吸血',healOverTime:'持续恢复',shield:'护盾',burn:'灼烧',bleed:'流血'};
const sourceName=id=>{const key=String(id??'').replace(/^skill:/,'');return SKILL_TREE_DEFINITION.nodes.find(n=>n.id===key)?.name??(key.startsWith('reactor:')?'永燃反应炉':key==='shelter'?'绝境庇护':key||'未知来源');};
const seconds=ms=>(Math.max(0,ms)/1000).toFixed(1)+'秒战斗时间';
export function readEnemyEffectRows(e,id){const enemy=e?.enemies?.find(u=>String(u.id)===String(id));if(!enemy||enemy.hp<=0)return [];const ledger=e.treeEffects,clock=finite(ledger?.clock),sources=(ledger?.enemies?.[id]?.sources??[]).filter(x=>x.endAt>clock),has=status=>sources.some(x=>x.status===status),rows=sources.filter(x=>!x.requiresStatus||has(x.requiresStatus)).map(x=>({key:x.status??x.type,label:effectNames[x.status??x.type]??x.type,amount:x.amount,remainingMs:x.endAt-clock,source:sourceName(x.source?.id??x.sourceId),effective:x.type==='dot'||x.amount===Math.max(...sources.filter(y=>y.type===x.type&&(!y.requiresStatus||has(y.requiresStatus))).map(y=>y.amount))}));const poison=e.treePoison?.[id],layers=(poison?.layers??[]).filter(l=>l.expiresAt>poison.clock);if(layers.length)rows.push({key:'poison',label:'中毒',layers:layers.length,amount:2,remainingMs:Math.max(...layers.map(l=>l.expiresAt-poison.clock)),source:'撒灰',layerDetails:layers.map(l=>({remainingMs:l.expiresAt-poison.clock,nextMs:l.nextTickAt-poison.clock}))});return rows;}
export function renderEnemyEffectDetails(e,id){const rows=readEnemyEffectRows(e,id);return '<h2>敌人状态</h2><p>按已结算战斗时钟显示；查看不会推进时间。同类削弱取最强，不叠加。</p>'+ (rows.length?rows.map(r=>`<section class="battleEffectDetail"><b>${esc(r.label)}${r.layers?' · '+r.layers+'层':''}</b><p>${esc(r.source)} · ${r.layers?'每层目标最大生命2%，先盾后生命，不受增伤影响':'数值 '+r.amount+(r.effective?' · 当前生效':' · 较弱来源保留')}</p><p>剩余 ${seconds(r.remainingMs)}</p>${r.layerDetails?.map((l,i)=>`<small>第${i+1}层：剩余 ${seconds(l.remainingMs)} · 下次结算 ${seconds(l.nextMs)}</small>`).join('')??''}</section>`).join(''):'<p>暂无有效状态。</p>');}
export function readPlayerShieldRows(e){if(!e)return [];if(e.playerShieldLayers){const ledger=e.playerShieldLayers;return ledger.layers.filter(l=>l.remaining>0&&(l.expiresAt===null||l.expiresAt>ledger.clock)).map(l=>({source:sourceName(l.source),remaining:l.remaining,capacity:l.capacity,remainingMs:l.expiresAt===null?null:l.expiresAt-ledger.clock}));}return [['旧版护盾',e.shield],['旧版壁垒',e.barrierShield]].filter(([,v])=>v>0).map(([source,remaining])=>({source,remaining,capacity:remaining,remainingMs:null}));}
export function renderPlayerShieldSummary(e){const rows=readPlayerShieldRows(e),total=rows.reduce((n,r)=>n+r.remaining,0);return total>0?`<button class="playerShieldSummary" data-player-shields="1" aria-label="查看自身护盾来源">${icon('shield')}<span>护盾 ${Math.ceil(total)}</span></button>`:'';}
export function renderPlayerShieldDetails(e){const rows=readPlayerShieldRows(e);return `<h2>自身护盾 · ${Math.ceil(rows.reduce((n,r)=>n+r.remaining,0))}</h2><p>各来源独立；此处仅查看，不推进战斗时钟。</p>`+(rows.map(r=>`<section class="battleEffectDetail"><b>${esc(r.source)}</b><p>剩余 ${r.remaining} / ${r.capacity}</p><small>${r.remainingMs===null?'无计时到期':seconds(r.remainingMs)}</small></section>`).join('')||'<p>暂无有效护盾。</p>');}
function typedStatusChips(e,id){const rows=readEnemyEffectRows(e,id),seen=new Set();return rows.filter(r=>{if(seen.has(r.key))return false;seen.add(r.key);return true;}).map(r=>`<button class="typedEffectChip" data-enemy-effects="${esc(id)}" title="${esc(r.label)}" aria-label="查看${esc(r.label)}状态">${icon(r.key==='poison'?'herb':r.key==='burn'?'fire':r.key==='bleed'?'sword':'shield')}<span>${esc(r.label)}${r.layers?' '+r.layers+'层':''}</span></button>`).join('');}
export function normalizeBattleEnemies(encounter,now=Date.now()){
 if(!encounter)return [];
 if(Number.isFinite(encounter.pauseAt))now=encounter.pauseAt;
 const units=Array.isArray(encounter.enemies)?encounter.enemies:[{...encounter,id:encounter.id??'legacy-main',shield:encounter.enemyShield??0,main:true}];
 const targetId=encounter.targetId??encounter.selectedTargetId??units.find(u=>u.main&&u.hp>0)?.id??units.find(u=>u.hp>0)?.id;
 return units.map((u,index)=>{
  const max=Math.max(1,finite(u.maxHp,finite(u.max,1))),hp=clamp(finite(u.hp),0,max),shield=Math.max(0,finite(u.enemyShield,finite(u.shield))),control=u.control??{},cast=u.preparing??control.preparing;
  let preparing=null;
  if(cast&&Number.isFinite(cast.startedAt)&&Number.isFinite(cast.completesAt)&&cast.completesAt>cast.startedAt){const total=Math.max(1,finite(cast.duration,finite(cast.totalDuration,cast.completesAt-cast.startedAt))),pausedElapsed=Number.isFinite(control.clock)&&cast.completesAt>control.clock?Math.max(0,Math.min(now,finite(control.stunUntil))-control.clock):0,remaining=Math.max(0,cast.completesAt+pausedElapsed-now);preparing={name:DWARF_MONSTERS[u.definitionId]?.skills.find(skill=>skill.id===cast.skillId)?.name??cast.name??cast.skillName??'施法准备',progress:clamp(1-remaining/total),paused:finite(control.stunUntil)>now};}
  const statuses=[];for(const [key,label]of [['burn','灼烧'],['broken','破甲'],['scorch','炉蚀'],['blunt','削弱'],['slow','迟缓'],['stun','眩晕']]){const value=u[key]??u.statuses?.[key]?.turns;if(value>0)statuses.push({key,label,remaining:value});}
  if(finite(control.stunUntil)>now&&!statuses.some(x=>x.key==='stun'))statuses.push({key:'stun',label:'眩晕',remaining:null});
  return {id:String(u.id??'enemy-'+index),definitionId:u.definitionId??u.monsterId??null,name:u.name??'敌人',hp,max,shield,main:!!u.main,follower:u.follower===true,summoned:u.origin==='summoned'||u.summoned===true,selected:hp>0&&String(u.id??'enemy-'+index)===String(targetId),dead:hp<=0,preparing,statuses,artLocation:u.artLocation??u.location??encounter.location??0,boss:u.boss??(u.main?encounter.boss??false:false)};
 });
}
function portrait(unit){return renderMonsterPixelPortrait(unit.definitionId,{known:true,follower:unit.follower});}
export function renderEnemyRoster(encounter,{now=Date.now()}={}){
 const units=normalizeBattleEnemies(encounter,now);if(!units.length)return '';
 return `<div class="multiEnemyRoster" aria-label="同场敌人">${units.map(u=>`<div class="enemyUnitCard ${u.selected?'isTarget':''} ${u.dead?'isDefeated':''}" data-unit-id="${esc(u.id)}"><button class="enemyPortrait" data-enemy-target="${esc(u.id)}" aria-label="${u.dead?'已击败':'选中'}${esc(u.name)}" aria-pressed="${u.selected}" ${u.dead||encounter.done?'disabled':''}>${portrait(u)}</button><div class="enemyUnitVitals"><div class="enemyUnitName"><b>${esc(u.name)}</b>${u.main?'<span class="enemyMainBadge">主</span>':''}${u.summoned?'<span class="enemySummonBadge">召</span>':''}<button class="enemyUnitInfo" data-monster-detail="${esc(u.definitionId??u.id)}" data-unit-detail="${esc(u.id)}" aria-label="查看${esc(u.name)}资料">ⓘ</button></div><div class="enemyUnitHp" role="progressbar" aria-label="生命" aria-valuemin="0" aria-valuemax="${u.max}" aria-valuenow="${u.hp}"><i style="width:${u.hp/u.max*100}%"></i><span>${Math.ceil(u.hp)}/${Math.ceil(u.max)}</span></div>${!u.dead?`<div class="typedEnemyStatuses">${typedStatusChips(encounter,u.id)}</div>`:''}${u.shield>0?`<div class="enemyUnitShield" title="护盾 ${Math.ceil(u.shield)}"><i style="width:${clamp(u.shield/u.max)*100}%"></i><span>盾 ${Math.ceil(u.shield)}</span></div>`:''}${u.preparing&&!u.dead?`<div class="enemyUnitCast ${u.preparing.paused?'isPaused':''}" role="progressbar" aria-label="${u.preparing.paused?'眩晕暂停 · ':''}${esc(u.preparing.name)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(u.preparing.progress*100)}"><i style="width:${u.preparing.progress*100}%"></i><span>${u.preparing.paused?'暂停 · ':''}${esc(u.preparing.name)}</span></div>`:''}${u.statuses.length&&!u.dead?`<div class="enemyMiniStatuses">${u.statuses.map(x=>`<span title="${esc(x.label)}${x.remaining?' · '+x.remaining+'回合':''}">${esc(x.label)}${x.remaining?'<b>'+x.remaining+'</b>':''}</span>`).join('')}</div>`:''}</div></div>`).join('')}</div>`;
}
export function bindEnemyRoster(host,{readEncounter,onSelect,onInspect}){
 const listener=event=>{const detail=event.target.closest?.('[data-unit-detail]');if(detail&&host.contains(detail)){onInspect?.(detail.dataset.unitDetail,detail.dataset.monsterDetail);return;}const button=event.target.closest?.('[data-enemy-target]');if(!button||!host.contains(button)||button.disabled)return;const e=readEncounter(),u=normalizeBattleEnemies(e).find(x=>x.id===button.dataset.enemyTarget);if(u&&!u.dead&&!e.done)onSelect(u.id);};host.addEventListener('click',listener);return ()=>host.removeEventListener('click',listener);
}
export function bindSceneTargets(canvas,{readEncounter,onSelect}){
 const listener=event=>{const e=readEncounter(),units=normalizeBattleEnemies(e);if(!e||e.done||!units.length)return;const box=canvas.getBoundingClientRect();if(!box.width||!box.height)return;const x=(event.clientX-box.left)*960/box.width,y=(event.clientY-box.top)*420/box.height;const layout=enemySceneLayout(units.length);const hit=layout.findIndex(p=>x>=p.x-55*p.scale&&x<=p.x+55*p.scale&&y>=p.y-168*p.scale&&y<=p.y+16);if(hit>=0&&!units[hit].dead)onSelect(units[hit].id);};canvas.addEventListener('click',listener);return ()=>canvas.removeEventListener('click',listener);
}
// Existing arrows remain app-owned; this only adds drag/drop without a duplicate click path.
export function enhanceSkillPriority(host,{readState,onMove}){
 let from=null,snapshot=null;const fingerprint=()=>{const s=readState();return JSON.stringify([s.skills,s.conditions]);};const node=event=>{const n=event.target.closest?.('.skillSlot');return n&&host.contains(n)?n:null;};const slots=()=>Array.from(host.querySelectorAll?.('.skillSlot')??[]);
 slots().forEach((n,i)=>{n.draggable=true;n.dataset.priorityIndex=String(i);n.title='拖动调整施放优先级，也可使用左右箭头';});
 const handlers={dragstart:event=>{const n=node(event);from=n?slots().indexOf(n):null;snapshot=from!==null?fingerprint():null;if(from!==null&&event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(from));}},dragover:event=>{if(from!==null&&node(event))event.preventDefault();},drop:event=>{const n=node(event);if(from!==null&&n&&snapshot===fingerprint()){event.preventDefault();const to=slots().indexOf(n);if(to>=0&&to!==from)onMove(from,to);}from=null;snapshot=null;},dragend:()=>{from=null;snapshot=null;}};for(const [k,fn]of Object.entries(handlers))host.addEventListener(k,fn);return ()=>{for(const [k,fn]of Object.entries(handlers))host.removeEventListener(k,fn);from=null;};
}
